import React from 'react';
import Layout from '../components/Layout'; // Import the Layout component
import EnquiryForm from '../components/EnquiryForm'; // Import EnquiryForm component
import Address from '../components/Address'; // Import Address component
import Services from '../components/Services'; // Import Services component
import Projects from '../components/Projects'; // Import Projects component

import SocialMedia from '../components/SocialMedia';


function Home() {
  return (
    <Layout>
    <div className="home">
      <section className="hero">
        <div className="hero-content">
          <h2>Paving the Way for a <span className="highlight">Cleaner, Brighter Tomorrow</span> </h2>
        </div>
      </section>

      {/* Include various components */}


      <Services />
      <Projects />
      <EnquiryForm />
      <SocialMedia />
      <Address />
    </div>
    </Layout>
  );
}

export default Home;
